        List<DisclosurePackage> rows = jdbc.query(
                "SELECT * FROM disclosure_package WHERE package_key = ? FOR UPDATE",
                ROW_MAPPER, packageKey);
        return rows.stream().findFirst();
    }

    /**
     * 按版本顺序列出案件全部包（含已交付与已撤销）。
     */
