        // 注入一条不连续的历史交接（from=dave 与位置 bob 不连续），钉在截至时刻前。
        jdbc.update("""
                        INSERT INTO transfer_record
                            (evidence_key, from_custodian, to_custodian, status, initiated_by,
                             created_at, decided_at)
                        VALUES (?, 'dave', 'erin', 'ACCEPTED', 'dave', ?, ?)
