        // 用 T2 覆盖诊断：尽管当前已归还，截至 T2 仍借出未归还。
        MvcResult diagnosis = mockMvc.perform(get(
                        "/api/disclosure/packages/{key}/items/{ev}/diagnosis", packageKey, ev)
